INSERT INTO public.schemes (name, slug, level, state, category, department, description, benefits, eligibility_rules, eligibility_notes, documents, application_process, beneficiary_type, official_source, official_website, official_application_url, last_verified_date) VALUES
('Pradhan Mantri Kisan Samman Nidhi (PM-KISAN)','pm-kisan','central',NULL,'Farmers','Ministry of Agriculture and Farmers Welfare','Income support scheme providing financial assistance to land-holding farmer families across India, paid directly into bank accounts in three instalments.',ARRAY['Rs 6,000 per year in three equal instalments of Rs 2,000','Direct Benefit Transfer to the bank account'],'{"farmer":true,"min_age":18}'::jsonb,ARRAY['Land-holding farmer family with cultivable land in their name','Institutional land holders and higher income tax payers are excluded'],ARRAY['Aadhaar card','Land ownership records','Bank account details'],ARRAY['Visit the PM-KISAN portal or your village nodal officer','Complete New Farmer Registration with Aadhaar and land details','Track beneficiary status on the portal'],ARRAY['Farmer'],'PM-KISAN Portal, Ministry of Agriculture and Farmers Welfare','https://pmkisan.gov.in','https://pmkisan.gov.in/RegistrationFormnew.aspx','2025-01-01'),
('Pradhan Mantri Fasal Bima Yojana (PMFBY)','pmfby','central',NULL,'Agriculture','Ministry of Agriculture and Farmers Welfare','Crop insurance scheme that protects farmers against crop loss due to natural calamities, pests and diseases at a low premium.',ARRAY['Insurance cover for notified crops','Farmer premium capped at 2% for Kharif, 1.5% for Rabi and 5% for commercial crops'],'{"farmer":true}'::jsonb,ARRAY['All farmers growing notified crops in notified areas, including sharecroppers and tenant farmers'],ARRAY['Aadhaar card','Land records or tenancy agreement','Sowing certificate','Bank account details'],ARRAY['Apply through the PMFBY portal, a bank branch, CSC or an insurance intermediary','Pay the farmer share of premium before the cut-off date','Report crop loss within 72 hours of the event'],ARRAY['Farmer'],'PMFBY Portal, Ministry of Agriculture and Farmers Welfare','https://pmfby.gov.in','https://pmfby.gov.in/farmerRegistrationForm','2025-01-01'),
('Kisan Credit Card (KCC) Scheme','kisan-credit-card','central',NULL,'Agriculture','Ministry of Agriculture and Farmers Welfare / NABARD','Short-term credit facility for farmers to meet cultivation and allied activity expenses, with interest subvention on timely repayment.',ARRAY['Short-term crop loans at concessional interest','Interest subvention and prompt repayment incentive','Flexible withdrawal and repayment'],'{"farmer":true,"min_age":18}'::jsonb,ARRAY['Farmers who are owner cultivators, tenant farmers, oral lessees or sharecroppers','Also open to animal husbandry and fisheries activities'],ARRAY['Aadhaar card','Land documents','Passport size photograph','Bank account details'],ARRAY['Visit your bank branch or apply online through the bank','Submit the KCC application with land and identity documents','Sanctioned limit is issued as a card or credit limit'],ARRAY['Farmer'],'Ministry of Agriculture and Farmers Welfare','https://agriwelfare.gov.in','https://www.jansamarth.in','2025-01-01'),
('Pradhan Mantri Kisan Maandhan Yojana','pm-kisan-maandhan','central',NULL,'Farmers','Ministry of Agriculture and Farmers Welfare','Voluntary contributory pension scheme for small and marginal farmers, with a matching contribution from the Government of India.',ARRAY['Assured monthly pension of Rs 3,000 after the age of 60','Government matches the farmer contribution'],'{"farmer":true,"min_age":18,"max_age":40}'::jsonb,ARRAY['Small and marginal farmers aged 18 to 40 years','Cultivable land up to 2 hectares'],ARRAY['Aadhaar card','Bank account with IFSC','Land records'],ARRAY['Enrol at a Common Service Centre or on the Maandhan portal','Choose the monthly contribution based on entry age','Contributions are auto-debited from the bank account'],ARRAY['Farmer'],'PM Kisan Maandhan Portal','https://maandhan.in','https://maandhan.in/scheme/pmkmy','2025-01-01'),
('Soil Health Card Scheme','soil-health-card','central',NULL,'Agriculture','Ministry of Agriculture and Farmers Welfare','Provides farmers with soil nutrient status of their holdings along with crop-wise recommendations on fertiliser use.',ARRAY['Free soil testing and soil health report','Crop-wise nutrient and fertiliser recommendations'],'{"farmer":true}'::jsonb,ARRAY['All farmers with agricultural land holdings'],ARRAY['Aadhaar card','Land records'],ARRAY['Contact the local agriculture office or soil testing lab','Provide a soil sample from your field','Collect the Soil Health Card with recommendations'],ARRAY['Farmer'],'Soil Health Card Portal','https://soilhealth.dac.gov.in','https://soilhealth.dac.gov.in','2025-01-01'),
('Pradhan Mantri Ujjwala Yojana (PMUY)','pmuy','central',NULL,'Women','Ministry of Petroleum and Natural Gas','Provides deposit-free LPG connections to women from poor households to promote clean cooking fuel.',ARRAY['Deposit-free LPG connection in the name of an adult woman','Financial support for the first refill and stove'],'{"gender":["Female"],"min_age":18,"max_income":300000}'::jsonb,ARRAY['Adult woman from a poor household as defined by the scheme lists','No existing LPG connection in the household'],ARRAY['Aadhaar card','Ration card or supporting poverty proof','Bank account details','Address proof'],ARRAY['Apply on the Ujjwala portal or at an LPG distributor','Submit the KYC form with documents','Collect the connection from the distributor'],ARRAY['Woman','Family'],'PMUY Portal, Ministry of Petroleum and Natural Gas','https://www.pmuy.gov.in','https://www.pmuy.gov.in/ujjwala2.html','2025-01-01'),
('Pradhan Mantri Awas Yojana - Gramin','pmay-gramin','central',NULL,'Housing','Ministry of Rural Development','Assistance to rural households that are houseless or living in kutcha houses to build a pucca house with basic amenities.',ARRAY['Financial assistance for house construction in instalments','Support convergence with toilet, LPG and electricity schemes'],'{"max_income":300000}'::jsonb,ARRAY['Rural households identified as houseless or in kutcha or dilapidated houses','Selection is based on official deprivation criteria and Gram Sabha verification'],ARRAY['Aadhaar card','Bank account details','Job card if available','Land or site documents'],ARRAY['Verify your name in the beneficiary list with the Gram Panchayat','Complete registration with the block office','Instalments are released after construction milestones'],ARRAY['Family'],'PMAY-G Portal, Ministry of Rural Development','https://pmayg.nic.in','https://pmayg.nic.in','2025-01-01'),
('Pradhan Mantri Awas Yojana - Urban','pmay-urban','central',NULL,'Housing','Ministry of Housing and Urban Affairs','Housing mission for urban poor offering interest subsidy and construction assistance for affordable housing.',ARRAY['Credit linked interest subsidy on home loans','Assistance for beneficiary-led construction and affordable housing units'],'{"max_income":1800000}'::jsonb,ARRAY['Urban households in EWS, LIG or MIG income categories','The family should not own a pucca house anywhere in India'],ARRAY['Aadhaar card','Income proof','Bank account details','Property or site documents'],ARRAY['Apply through the PMAY-U portal or your urban local body','Submit income and identity documents','Track application status online'],ARRAY['Family'],'PMAY-U Portal, Ministry of Housing and Urban Affairs','https://pmay-urban.gov.in','https://pmay-urban.gov.in','2025-01-01'),
('Ayushman Bharat PM Jan Arogya Yojana (PM-JAY)','pm-jay','central',NULL,'Health','National Health Authority','Health assurance scheme providing cashless secondary and tertiary hospital treatment to eligible families at empanelled hospitals.',ARRAY['Health cover of Rs 5 lakh per family per year','Cashless treatment at empanelled public and private hospitals','No cap on family size or age'],'{"max_income":300000}'::jsonb,ARRAY['Families identified through the official deprivation and occupational criteria','Senior citizens aged 70 and above are covered under the extended vertical'],ARRAY['Aadhaar card','Ration card or family ID','Mobile number'],ARRAY['Check eligibility on the PM-JAY portal or call 14555','Complete verification at a Common Service Centre or empanelled hospital','Receive the Ayushman card and use it at empanelled hospitals'],ARRAY['Family','Senior Citizen'],'National Health Authority','https://pmjay.gov.in','https://beneficiary.nha.gov.in','2025-01-01'),
('Sukanya Samriddhi Yojana','sukanya-samriddhi','central',NULL,'Child Welfare','Ministry of Finance / Department of Posts','Small savings scheme for a girl child that offers attractive interest and tax benefits to build funds for education and marriage.',ARRAY['High fixed interest revised quarterly','Tax benefits under Section 80C','Partial withdrawal allowed for higher education'],'{"gender":["Female"],"max_age":10}'::jsonb,ARRAY['Account can be opened by a guardian for a girl child below 10 years','Maximum two accounts per family, with exceptions for twins'],ARRAY['Birth certificate of the girl child','Guardian identity and address proof','Photographs'],ARRAY['Visit a post office or authorised bank branch','Submit the SSY account opening form with documents','Deposit between Rs 250 and Rs 1.5 lakh every financial year'],ARRAY['Girl Child'],'Department of Posts, India Post','https://www.indiapost.gov.in','https://www.indiapost.gov.in/Financial/pages/content/post-office-saving-schemes.aspx','2025-01-01'),
('Pradhan Mantri Matru Vandana Yojana (PMMVY)','pmmvy','central',NULL,'Women','Ministry of Women and Child Development','Maternity benefit programme providing cash incentive to pregnant women and lactating mothers for wage loss and better nutrition.',ARRAY['Cash incentive paid in instalments directly to the bank account','Additional incentive for the second child if it is a girl'],'{"gender":["Female"],"min_age":19}'::jsonb,ARRAY['Pregnant women and lactating mothers aged 19 years and above','Government employees receiving similar paid benefits are excluded'],ARRAY['Aadhaar card','Mother and child protection card','Bank or post office account details'],ARRAY['Register at the nearest Anganwadi centre or approved health facility','Submit the form with Aadhaar and bank details','Instalments are released after pregnancy and immunisation milestones'],ARRAY['Woman'],'PMMVY Portal, Ministry of Women and Child Development','https://pmmvy.wcd.gov.in','https://pmmvy.wcd.gov.in','2025-01-01'),
('Beti Bachao Beti Padhao','beti-bachao-beti-padhao','central',NULL,'Child Welfare','Ministry of Women and Child Development','National initiative to prevent gender-biased sex selection and promote the survival, protection and education of the girl child.',ARRAY['Community awareness and advocacy for girl child rights','Support for girls education and enrolment drives'],'{"gender":["Female"]}'::jsonb,ARRAY['A community-level awareness and convergence scheme rather than a direct cash transfer'],ARRAY['No individual application documents required'],ARRAY['Engage through district administration and Anganwadi programmes','Follow district level campaigns and services'],ARRAY['Girl Child','Woman'],'Ministry of Women and Child Development','https://wcd.gov.in','https://wcd.gov.in/bbbp-schemes','2025-01-01'),
('National Means-cum-Merit Scholarship Scheme (NMMSS)','nmmss','central',NULL,'Scholarships','Ministry of Education','Scholarship for meritorious students from economically weaker sections to reduce dropout at Class 8 and encourage study up to Class 12.',ARRAY['Scholarship of Rs 12,000 per year','Paid directly into the student bank account'],'{"student":true,"max_income":350000,"min_age":10,"max_age":20}'::jsonb,ARRAY['Students studying in Class 9 to 12 in government, local body or government-aided schools','Must clear the state level selection test and meet the marks criteria'],ARRAY['Aadhaar card','Income certificate','Previous year marksheet','Bank account details','Institution verification'],ARRAY['Appear for the state level NMMS selection test','Apply on the National Scholarship Portal within the deadline','Get the application verified by the institute and district authority'],ARRAY['Student'],'National Scholarship Portal, Ministry of Education','https://scholarships.gov.in','https://scholarships.gov.in','2025-01-01'),
('Post Matric Scholarship for SC Students','post-matric-scholarship-sc','central',NULL,'Scholarships','Ministry of Social Justice and Empowerment','Financial assistance to Scheduled Caste students studying at post matriculation or post secondary level to help them complete their education.',ARRAY['Maintenance allowance based on course group','Reimbursement of compulsory non-refundable fees'],'{"student":true,"categories":["SC"],"max_income":250000}'::jsonb,ARRAY['Students belonging to Scheduled Castes studying beyond Class 10','Parental annual income within the prescribed ceiling'],ARRAY['Caste certificate','Income certificate','Previous marksheet','Fee receipt','Bank account details'],ARRAY['Register on the National Scholarship Portal','Fill the application and upload documents','Institute and state department verify the application'],ARRAY['Student','SC'],'National Scholarship Portal, Ministry of Social Justice and Empowerment','https://scholarships.gov.in','https://scholarships.gov.in','2025-01-01'),
('Pre Matric Scholarship for ST Students','pre-matric-scholarship-st','central',NULL,'Scholarships','Ministry of Tribal Affairs','Scholarship for Scheduled Tribe students in Classes 9 and 10 to reduce dropout during the pre matric stage.',ARRAY['Monthly scholarship and annual book grant','Additional allowance for hostellers'],'{"student":true,"categories":["ST"],"max_income":250000}'::jsonb,ARRAY['Scheduled Tribe students studying in Class 9 or 10','Parental annual income within the prescribed ceiling'],ARRAY['Caste certificate','Income certificate','School bonafide certificate','Bank account details'],ARRAY['Apply on the National Scholarship Portal or the state portal','Upload caste and income certificates','School verifies enrolment'],ARRAY['Student','ST'],'National Scholarship Portal, Ministry of Tribal Affairs','https://scholarships.gov.in','https://scholarships.gov.in','2025-01-01'),
('AICTE Pragati Scholarship for Girl Students','aicte-pragati','central',NULL,'Scholarships','All India Council for Technical Education','Scholarship supporting girl students pursuing technical education in AICTE approved institutions.',ARRAY['Rs 50,000 per year for tuition fee and books','Support for up to two girls per family'],'{"student":true,"gender":["Female"],"max_income":800000}'::jsonb,ARRAY['Girl students admitted to the first year of a degree or diploma programme in an AICTE approved institution','Family income within the prescribed ceiling'],ARRAY['Aadhaar card','Admission proof','Income certificate','Class 12 or diploma marksheet','Bank account details'],ARRAY['Register on the National Scholarship Portal','Submit the Pragati application with documents','Institution verifies the application'],ARRAY['Student','Woman'],'AICTE, National Scholarship Portal','https://www.aicte-india.org','https://scholarships.gov.in','2025-01-01'),
('Pradhan Mantri Mudra Yojana (PMMY)','pm-mudra','central',NULL,'Finance','Ministry of Finance','Collateral free institutional loans up to Rs 10 lakh for non-farm micro and small enterprises under the Shishu, Kishore and Tarun categories.',ARRAY['Collateral free loans up to Rs 10 lakh','Three loan categories based on business stage'],'{"min_age":18}'::jsonb,ARRAY['Indian citizens with a viable non-farm income generating business plan','Should not be a defaulter with any bank or financial institution'],ARRAY['Aadhaar and PAN','Business plan or quotation','Address proof','Bank statements'],ARRAY['Choose a bank, NBFC or MFI and submit the Mudra loan application','Provide business details and documents','Loan is sanctioned as term loan, working capital or overdraft'],ARRAY['Entrepreneur'],'MUDRA, Ministry of Finance','https://www.mudra.org.in','https://www.jansamarth.in','2025-01-01'),
('Stand-Up India Scheme','stand-up-india','central',NULL,'Entrepreneurship','Ministry of Finance / SIDBI','Bank loans for greenfield enterprises promoted by Scheduled Caste, Scheduled Tribe and women entrepreneurs.',ARRAY['Composite loan between Rs 10 lakh and Rs 1 crore','Handholding support and margin money assistance'],'{"min_age":18,"categories":["SC","ST"],"gender":["Female"]}'::jsonb,ARRAY['SC, ST or women entrepreneurs aged 18 and above','Greenfield project in manufacturing, services, trading or allied agriculture activities','For non-individual enterprises at least 51% shareholding should be held by SC, ST or women entrepreneurs'],ARRAY['Aadhaar and PAN','Caste certificate if applicable','Project report','Bank account details'],ARRAY['Register on the Stand-Up India portal','Prepare the project report with handholding support','Apply to the selected bank branch'],ARRAY['Entrepreneur','Woman','SC','ST'],'Stand-Up India Portal, SIDBI','https://www.standupmitra.in','https://www.standupmitra.in','2025-01-01'),
('Prime Minister Employment Generation Programme (PMEGP)','pmegp','central',NULL,'Employment','Ministry of MSME / KVIC','Credit linked subsidy programme to help unemployed youth set up micro enterprises in the non-farm sector.',ARRAY['Margin money subsidy of 15% to 35% of project cost','Project cost up to Rs 50 lakh for manufacturing and Rs 20 lakh for service units'],'{"min_age":18}'::jsonb,ARRAY['Individuals above 18 years setting up a new micro enterprise','At least Class 8 pass for projects above the prescribed cost limits'],ARRAY['Aadhaar and PAN','Education certificate','Project report','Caste or special category certificate if applicable'],ARRAY['Apply online on the PMEGP e-portal','Attend the district task force interview','Complete EDP training and receive bank finance with subsidy'],ARRAY['Entrepreneur','Youth'],'KVIC PMEGP e-Portal, Ministry of MSME','https://www.kviconline.gov.in/pmegpeportal','https://www.kviconline.gov.in/pmegpeportal/pmegphome/index.jsp','2025-01-01'),
('PM Vishwakarma','pm-vishwakarma','central',NULL,'MSME','Ministry of MSME','Support scheme for traditional artisans and craftspeople offering recognition, skill training, toolkit incentive and collateral free credit.',ARRAY['Skill training with stipend','Toolkit incentive','Collateral free enterprise development loans at concessional interest'],'{"min_age":18}'::jsonb,ARRAY['Artisans and craftspeople aged 18 and above working in one of the notified trades','Should be engaged in the trade in a self employed capacity'],ARRAY['Aadhaar card','Bank account details','Mobile number linked to Aadhaar','Trade details'],ARRAY['Register through a Common Service Centre or the PM Vishwakarma portal','Complete verification at panchayat or urban local body level','Receive the digital ID and access training and credit'],ARRAY['Artisan','Entrepreneur'],'PM Vishwakarma Portal, Ministry of MSME','https://pmvishwakarma.gov.in','https://pmvishwakarma.gov.in','2025-01-01'),
('PM Street Vendor AtmaNirbhar Nidhi (PM SVANidhi)','pm-svanidhi','central',NULL,'Finance','Ministry of Housing and Urban Affairs','Micro credit facility for urban street vendors to resume and grow their businesses, with incentives for digital transactions.',ARRAY['Working capital loan starting at Rs 10,000 with escalating limits','Interest subsidy on timely repayment and digital transaction cashback'],'{"min_age":18,"occupations":["Street Vendor","Self-employed","Daily Wage Worker"]}'::jsonb,ARRAY['Urban street vendors with a certificate of vending or identified in the urban local body survey'],ARRAY['Certificate of vending or letter of recommendation','Aadhaar card','Bank account details'],ARRAY['Apply through the PM SVANidhi portal, a bank or a lending institution','Urban local body verifies vendor status','Loan is credited to the bank account'],ARRAY['Street Vendor','Entrepreneur'],'PM SVANidhi Portal, Ministry of Housing and Urban Affairs','https://pmsvanidhi.mohua.gov.in','https://pmsvanidhi.mohua.gov.in','2025-01-01'),
('Atal Pension Yojana (APY)','atal-pension-yojana','central',NULL,'Social Welfare','Ministry of Finance / PFRDA','Guaranteed pension scheme for workers in the unorganised sector with pension amounts depending on contribution and entry age.',ARRAY['Guaranteed monthly pension from Rs 1,000 to Rs 5,000 after age 60','Spouse and nominee benefits'],'{"min_age":18,"max_age":40}'::jsonb,ARRAY['Indian citizens aged 18 to 40 years with a savings bank account','Income tax payers are not eligible to join'],ARRAY['Aadhaar card','Savings bank account','Mobile number'],ARRAY['Submit the APY form at your bank or through net banking','Choose the pension amount and contribution frequency','Contributions are auto debited until the age of 60'],ARRAY['Worker','Unorganised Sector'],'PFRDA, Ministry of Finance','https://www.npscra.nsdl.co.in/scheme-details.php','https://enps.nsdl.com','2025-01-01'),
('Pradhan Mantri Jeevan Jyoti Bima Yojana (PMJJBY)','pmjjby','central',NULL,'Social Welfare','Ministry of Finance','Renewable one year term life insurance scheme offering life cover at a very low annual premium.',ARRAY['Life cover of Rs 2 lakh','Low annual premium auto debited from the bank account'],'{"min_age":18,"max_age":50}'::jsonb,ARRAY['Account holders aged 18 to 50 years with a bank or post office savings account','Cover continues up to age 55 subject to premium payment'],ARRAY['Aadhaar card','Bank account details','Consent cum declaration form'],ARRAY['Give consent at your bank or through net banking','Premium is auto debited annually','Nominee claims through the bank branch'],ARRAY['Worker','Family'],'Jan Suraksha, Ministry of Finance','https://jansuraksha.gov.in','https://jansuraksha.gov.in','2025-01-01'),
('Pradhan Mantri Suraksha Bima Yojana (PMSBY)','pmsby','central',NULL,'Social Welfare','Ministry of Finance','Accident insurance scheme providing accidental death and disability cover at a nominal annual premium.',ARRAY['Accidental death and permanent total disability cover of Rs 2 lakh','Partial disability cover of Rs 1 lakh'],'{"min_age":18,"max_age":70}'::jsonb,ARRAY['Bank or post office account holders aged 18 to 70 years'],ARRAY['Aadhaar card','Bank account details','Consent cum declaration form'],ARRAY['Enrol at your bank branch or through net banking','Premium is auto debited annually','Claim is filed by the nominee or insured through the bank'],ARRAY['Worker','Family'],'Jan Suraksha, Ministry of Finance','https://jansuraksha.gov.in','https://jansuraksha.gov.in','2025-01-01'),
('Indira Gandhi National Old Age Pension Scheme (IGNOAPS)','ignoaps','central',NULL,'Senior Citizens','Ministry of Rural Development','Central pension assistance to elderly persons living below the poverty line under the National Social Assistance Programme.',ARRAY['Monthly central pension assistance with higher amount after age 80','Often topped up by state contributions'],'{"min_age":60,"max_income":100000}'::jsonb,ARRAY['Persons aged 60 years and above belonging to a below poverty line household'],ARRAY['Age proof','BPL or income certificate','Aadhaar card','Bank account details'],ARRAY['Apply at the block office, panchayat or urban local body','Verification by the sanctioning authority','Pension is credited monthly to the bank account'],ARRAY['Senior Citizen'],'NSAP Portal, Ministry of Rural Development','https://nsap.nic.in','https://nsap.nic.in','2025-01-01'),
('Indira Gandhi National Disability Pension Scheme (IGNDPS)','igndps','central',NULL,'Disability','Ministry of Rural Development','Monthly pension for persons with severe or multiple disabilities from below poverty line households.',ARRAY['Monthly disability pension under the National Social Assistance Programme'],'{"disability":true,"min_age":18,"max_income":100000}'::jsonb,ARRAY['Persons aged 18 years and above with 80% or more disability','Belonging to a below poverty line household'],ARRAY['Disability certificate','BPL or income certificate','Aadhaar card','Bank account details'],ARRAY['Apply through the block office or urban local body','Disability and income verification','Pension is credited monthly'],ARRAY['Person with Disability'],'NSAP Portal, Ministry of Rural Development','https://nsap.nic.in','https://nsap.nic.in','2025-01-01'),
('Assistance to Disabled Persons for Purchase of Aids and Appliances (ADIP)','adip','central',NULL,'Disability','Department of Empowerment of Persons with Disabilities','Provides durable and scientifically manufactured aids and assistive devices to persons with disabilities, free or at subsidised cost.',ARRAY['Free aids and appliances for lower income beneficiaries','Subsidised cost for higher income slabs'],'{"disability":true}'::jsonb,ARRAY['Persons with 40% or more disability certified by a competent authority','Monthly income within the limits prescribed by the scheme'],ARRAY['Disability certificate','Income certificate','Aadhaar card','Photograph'],ARRAY['Attend an ADIP assessment camp or approach an implementing agency such as ALIMCO','Get assessed for the required assistive device','Receive the device at the distribution camp'],ARRAY['Person with Disability'],'Department of Empowerment of Persons with Disabilities','https://disabilityaffairs.gov.in','https://www.alimco.in','2025-01-01'),
('Mahatma Gandhi National Rural Employment Guarantee Scheme (MGNREGS)','mgnregs','central',NULL,'Rural Development','Ministry of Rural Development','Legal guarantee of at least 100 days of wage employment in a financial year to rural households whose adult members volunteer for unskilled manual work.',ARRAY['Up to 100 days of guaranteed wage employment per rural household','Wages paid directly to bank or post office accounts','Unemployment allowance if work is not provided in time'],'{"min_age":18}'::jsonb,ARRAY['Adult members of a rural household willing to do unskilled manual work','Household must be registered and hold a job card'],ARRAY['Aadhaar card','Proof of residence','Photographs','Bank account details'],ARRAY['Apply for a job card at the Gram Panchayat','Submit a written demand for work','Work is allotted within 15 days of demand'],ARRAY['Worker','Family'],'NREGA Portal, Ministry of Rural Development','https://nrega.nic.in','https://nrega.nic.in','2025-01-01'),
('Pradhan Mantri Kaushal Vikas Yojana (PMKVY)','pmkvy','central',NULL,'Skill Development','Ministry of Skill Development and Entrepreneurship','Flagship skill development scheme offering short term training, upskilling and recognition of prior learning with certification.',ARRAY['Free short term skill training and certification','Placement assistance and recognition of prior learning'],'{"min_age":15,"max_age":45}'::jsonb,ARRAY['Indian citizens who are unemployed, school or college dropouts or seeking upskilling','Age criteria varies by course, generally 15 to 45 years'],ARRAY['Aadhaar card','Education certificates','Bank account details'],ARRAY['Register on the Skill India Digital portal','Select a course and training centre','Complete training and assessment to receive certification'],ARRAY['Youth','Student','Worker'],'Skill India Digital, Ministry of Skill Development and Entrepreneurship','https://www.skillindiadigital.gov.in','https://www.skillindiadigital.gov.in','2025-01-01'),
('Deen Dayal Upadhyaya Grameen Kaushalya Yojana (DDU-GKY)','ddu-gky','central',NULL,'Employment','Ministry of Rural Development','Placement linked skill development programme for rural poor youth to help them move into regular wage employment.',ARRAY['Free residential or non residential skill training','Placement support with minimum salary assurance','Post placement support'],'{"min_age":15,"max_age":35}'::jsonb,ARRAY['Rural youth aged 15 to 35 years from poor households','Age relaxation for women and vulnerable groups as per guidelines'],ARRAY['Aadhaar card','Proof of rural residence','Education certificates','Bank account details'],ARRAY['Contact a DDU-GKY project implementing agency or the district skill office','Complete counselling and enrolment','Attend training and placement drives'],ARRAY['Youth','Worker'],'DDU-GKY, Ministry of Rural Development','https://ddugky.gov.in','https://ddugky.gov.in','2025-01-01'),
('PM POSHAN (Mid Day Meal Scheme)','pm-poshan','central',NULL,'Child Welfare','Ministry of Education','Provides one hot cooked nutritious meal to children in government and government aided schools to improve nutrition and attendance.',ARRAY['One hot cooked mid day meal on all school days','Improved nutrition and school attendance'],'{"student":true,"min_age":3,"max_age":16}'::jsonb,ARRAY['Children studying in balvatika and Classes 1 to 8 in government and government aided schools'],ARRAY['School enrolment record'],ARRAY['Benefit is delivered automatically to enrolled students','No separate application is needed'],ARRAY['Student','Child'],'Ministry of Education','https://pmposhan.education.gov.in','https://pmposhan.education.gov.in','2025-01-01'),
('National Apprenticeship Promotion Scheme (NAPS)','naps','central',NULL,'Youth','Ministry of Skill Development and Entrepreneurship','Promotes apprenticeship training by sharing stipend cost with employers and helping youth gain on the job industry experience.',ARRAY['Stipend during apprenticeship with government sharing a part of the cost','Industry recognised apprenticeship certificate'],'{"min_age":14,"max_age":35,"student":false}'::jsonb,ARRAY['Candidates aged 14 years and above who meet the qualification for the apprenticeship trade'],ARRAY['Aadhaar card','Education certificates','Bank account details','Photograph'],ARRAY['Register as a candidate on the Apprenticeship India portal','Apply for advertised apprenticeship opportunities','Join the establishment under a contract of apprenticeship'],ARRAY['Youth','Student'],'Apprenticeship India Portal','https://www.apprenticeshipindia.gov.in','https://www.apprenticeshipindia.gov.in','2025-01-01'),
